(()=>{
'use strict';
let active=null;
const center=()=>document.querySelectorAll('.video-row').forEach(row=>{const cards=[...row.children];const portraits=cards.filter(c=>!c.classList.contains('video-landscape'));const ref=Math.max(0,...(portraits.length?portraits:cards).map(c=>c.getBoundingClientRect().height));cards.filter(c=>c.classList.contains('video-landscape')).forEach(c=>c.style.setProperty('--center-offset',innerWidth>1000&&ref?Math.max(0,(ref-c.getBoundingClientRect().height)/2)+'px':'0px'))});
const resize=new ResizeObserver(center);document.querySelectorAll('.video-row').forEach(row=>resize.observe(row));document.fonts.ready.then(center);window.addEventListener('resize',center);
document.querySelectorAll('.sample-video').forEach(frame=>{
 const button=frame.querySelector('.sample-play'),image=button.querySelector('img');let retryThumb=false,timer;
 const recovery=document.createElement('div');recovery.className='media-recovery';recovery.hidden=true;const retry=document.createElement('button');retry.type='button';retry.textContent='Tentar novamente';const open=document.createElement('a');open.href=`https://drive.google.com/file/d/${encodeURIComponent(frame.dataset.driveId)}/view`;open.target='_blank';open.rel='noopener';open.textContent='Abrir vídeo em nova guia';recovery.append(retry,open);frame.after(recovery);
 image.addEventListener('error',()=>{if(!retryThumb){retryThumb=true;image.src=`https://drive.google.com/thumbnail?id=${encodeURIComponent(frame.dataset.driveId)}&sz=w400`}else{image.style.visibility='hidden';button.querySelector('.play-label').textContent='Clique para abrir o vídeo'}});image.addEventListener('load',()=>{image.style.visibility='visible';center()});
 const stop=()=>{clearTimeout(timer);frame.querySelector('iframe')?.remove();button.hidden=false;frame.classList.remove('is-loading');recovery.hidden=true};
 const play=()=>{if(active)active();stop();active=stop;const iframe=document.createElement('iframe');iframe.title=button.getAttribute('aria-label');iframe.allow='autoplay; fullscreen; picture-in-picture';iframe.allowFullscreen=true;iframe.src=`https://drive.google.com/file/d/${encodeURIComponent(frame.dataset.driveId)}/preview`;iframe.addEventListener('load',()=>{frame.classList.remove('is-loading')});button.hidden=true;frame.classList.add('is-loading');frame.append(iframe);recovery.hidden=false;iframe.focus();timer=setTimeout(()=>frame.classList.remove('is-loading'),15000);};button.addEventListener('click',play);retry.addEventListener('click',play);
});
document.querySelectorAll('.sample-image img').forEach(img=>{let tried=false;img.addEventListener('load',()=>img.parentElement.classList.remove('media-failed'));img.addEventListener('error',()=>{if(!tried){tried=true;const url=new URL(img.src,location.href);url.searchParams.set('v','100');img.src=url.href}else{img.parentElement.classList.add('media-failed')}})});
document.querySelectorAll('video').forEach(video=>{let panel;video.addEventListener('error',()=>{if(panel)return;panel=document.createElement('div');panel.className='media-recovery';const message=document.createElement('span');message.textContent='Não foi possível carregar este vídeo.';const retry=document.createElement('button');retry.type='button';retry.textContent='Tentar novamente';retry.addEventListener('click',()=>{const src=video.dataset.recordingSrc||video.currentSrc||video.getAttribute('src');if(src)video.src=src;video.controls=true;video.load();video.play().catch(()=>{})});panel.append(message,retry);const src=video.dataset.recordingSrc||video.currentSrc||video.getAttribute('src');if(src){const a=document.createElement('a');a.href=src;a.textContent='Abrir vídeo em nova guia';a.target='_blank';a.rel='noopener';panel.append(a)}video.parentElement.after(panel)});video.addEventListener('playing',()=>{panel?.remove();panel=null})});
const dialog=document.querySelector('.image-dialog');if(dialog){const img=dialog.querySelector('img'),caption=dialog.querySelector('figcaption');let opener;document.querySelectorAll('[data-enlarge]').forEach(button=>button.addEventListener('click',()=>{if(button.classList.contains('media-failed')){button.querySelector('img').src=button.dataset.enlarge+'?retry='+Date.now();return}opener=button;dialog.classList.toggle('logo-dialog',button.classList.contains('sample-logo'));img.src=button.dataset.enlarge;img.alt=button.dataset.title;caption.textContent=button.dataset.title;dialog.showModal()}));dialog.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});dialog.addEventListener('close',()=>opener?.focus())}
})();